// Usage score for the Simple mode chart sandbox, computed client-side from a
// player's game log (convex/infinileague/season/gameLog.ts). See
// docs/usage-score.md for the method; the weights and percentile tables are
// generated by scripts/usage-calibration/calibrate.py.
//
// Each week's carries, targets, and red-zone looks are valued in expected
// fantasy points for the league's scoring, then read as a percentile of
// weekly expected points across every RB/WR/TE (QBs against other QBs) -
// so a WR's 70 and an RB's 70 mean the same amount of fantasy opportunity.
// Belongs server-side eventually, keyed by player and week.

import {
  FLEX_CALIBRATION,
  QB_CALIBRATION,
  type UsageScoring,
  type UsageTeScoring,
} from "./usageCalibration";

export type UsagePosition = "QB" | "RB" | "WR" | "TE";

export interface UsageScoringConfig {
  scoring: UsageScoring;
  teScoring?: UsageTeScoring | undefined;
  sixPointPassTds?: boolean | undefined;
}

export interface GameLogLike {
  columns: Array<{ key: string }>;
  weeks: Array<{
    week: number;
    kind: "played" | "dnp" | "bye";
    values: Array<number | null>;
  }>;
}

// One week's usage: `total` is the 0-100 percentile, and pass/rush/rec split
// it by each part's share of the expected points, so the stack adds up.
export interface UsageWeek {
  week: number;
  kind: "played" | "dnp" | "bye";
  pass: number;
  rush: number;
  rec: number;
  total: number;
  // Expected fantasy points from the week's opportunities.
  expectedPoints: number;
}

export function isUsagePosition(position: string): position is UsagePosition {
  return position === "QB" || position === "RB" || position === "WR" || position === "TE";
}

// Percentile of `value` against 101 cut points (0th..100th), interpolated
// between the two it falls between.
function percentile(cuts: number[], value: number): number {
  if (value <= (cuts[0] ?? 0)) return 0;
  for (let index = 1; index < cuts.length; index += 1) {
    const upper = cuts[index]!;
    if (value <= upper) {
      const lower = cuts[index - 1]!;
      const share = upper > lower ? (value - lower) / (upper - lower) : 1;
      return index - 1 + share;
    }
  }
  return 100;
}

export function usageWeeks(
  log: GameLogLike,
  position: UsagePosition,
  config: UsageScoringConfig,
): UsageWeek[] {
  const index = new Map(log.columns.map((column, columnIndex) => [column.key, columnIndex]));
  const teScoring = config.teScoring ?? "NONE";
  const flex = FLEX_CALIBRATION[config.scoring][teScoring];
  const qb =
    QB_CALIBRATION[config.scoring][config.sixPointPassTds ? "sixPointPassTds" : "standard"];

  return log.weeks.map((week) => {
    const read = (key: string) => {
      const columnIndex = index.get(key);
      return columnIndex === undefined ? 0 : (week.values[columnIndex] ?? 0);
    };
    let pass = 0;
    let rush: number;
    let rec: number;
    let cuts: number[];
    if (position === "QB") {
      pass = read("pass_att") * qb.passAtt + read("pass_rz_att") * qb.passRzAtt;
      rush = read("rush_att") * qb.rushAtt + read("rush_rz_att") * qb.rushRzAtt;
      // A QB's rare catch, at the flex rate.
      rec = read("rec_tgt") * flex.recTgt + read("rec_rz_tgt") * flex.recRzTgt;
      cuts = qb.cuts;
    } else {
      rush = read("rush_att") * flex.rushAtt + read("rush_rz_att") * flex.rushRzAtt;
      rec =
        read("rec_tgt") * (flex.recTgt + (position === "TE" ? flex.teTgt : 0)) +
        read("rec_rz_tgt") * flex.recRzTgt;
      cuts = flex.cuts;
    }
    const expectedPoints = pass + rush + rec;
    const total = Math.round(percentile(cuts, expectedPoints));
    const part = (points: number) =>
      expectedPoints > 0 ? Math.round((total * points) / expectedPoints) : 0;
    // Rounded parts can miss the total by one - the largest part absorbs it.
    const parts = { pass: part(pass), rush: part(rush), rec: part(rec) };
    const largest = (Object.keys(parts) as Array<keyof typeof parts>).reduce((a, b) =>
      parts[a] >= parts[b] ? a : b,
    );
    parts[largest] += total - (parts.pass + parts.rush + parts.rec);
    return { week: week.week, kind: week.kind, ...parts, total, expectedPoints };
  });
}

// Mean usage score across the games he played (null before his first).
export function usageAverage(weeks: UsageWeek[]): number | null {
  const played = weeks.filter((week) => week.kind === "played");
  if (played.length === 0) return null;
  return played.reduce((sum, week) => sum + week.total, 0) / played.length;
}
